import React, { Component } from 'react';
import { EuiSelectable } from '../../../../src/components/selectable';
import { Options } from './data';

class _default extends Component {
  constructor(props) {
    super(props);
    this.state = {
      options: Options
    };
  }

  onChange = options => {
    this.setState({
      options
    });
  };

  render() {
    const {
      options
    } = this.state;
    return <EuiSelectable options={options} onChange={this.onChange} listProps={{
      bordered: true
    }}>
        {list => list}
      </EuiSelectable>;
  }

}

_default.propTypes = {};
export { _default as default };