module.exports = "// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n\n// This example JS is overly complex for simple icon usage\n// and is set up this way for ease of use in our docs.\n//\n// Check the snippet tab for a more common usage.\n\nimport React from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexItem,\n  EuiIcon,\n  EuiPanel,\n  EuiText,\n  EuiCopy,\n} from '../../../../src/components';\n\nconst iconTypes = [\n  'editorAlignCenter',\n  'editorAlignLeft',\n  'editorAlignRight',\n  'editorBold',\n  'editorCodeBlock',\n  'editorComment',\n  'editorDistributeHorizontal',\n  'editorDistributeVertical',\n  'editorHeading',\n  'editorItalic',\n  'editorItemAlignBottom',\n  'editorItemAlignCenter',\n  'editorItemAlignLeft',\n  'editorItemAlignMiddle',\n  'editorItemAlignRight',\n  'editorItemAlignTop',\n  'editorLink',\n  'editorOrderedList',\n  'editorPositionBottomLeft',\n  'editorPositionBottomRight',\n  'editorPositionTopLeft',\n  'editorPositionTopRight',\n  'editorRedo',\n  'editorStrike',\n  'editorTable',\n  'editorUnderline',\n  'editorUndo',\n  'editorUnorderedList',\n];\n\nexport default () => (\n  <EuiFlexGrid columns={4}>\n    {iconTypes.map(iconType => (\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n        key={iconType}\n        style={{ width: '200px' }}>\n        <EuiCopy textToCopy={iconType} afterMessage={`${iconType} copied`}>\n          {copy => (\n            <EuiPanel onClick={copy} className=\"eui-textCenter\">\n              <EuiIcon type={iconType} />\n              <EuiText size=\"s\">\n                <p>{iconType}</p>\n              </EuiText>\n            </EuiPanel>\n          )}\n        </EuiCopy>\n      </EuiFlexItem>\n    ))}\n  </EuiFlexGrid>\n);\n"