module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiColorPicker,\n  EuiFormRow,\n  EuiColorPickerSwatch,\n  EuiBadge,\n} from '../../../../src/components';\n\nimport { isValidHex } from '../../../../src/services';\n\nexport class CustomButton extends Component {\n  constructor(props) {\n    super(props);\n    this.state = {\n      color: null,\n    };\n  }\n\n  handleChange = value => {\n    this.setState({ color: value });\n  };\n\n  render() {\n    const hasErrors = !isValidHex(this.state.color) && this.state.color !== '';\n\n    let errors;\n    if (hasErrors) {\n      errors = ['Provide a valid hex value'];\n    }\n\n    return (\n      <Fragment>\n        <EuiFormRow label=\"Pick a color\" error={errors}>\n          <EuiColorPicker\n            onChange={this.handleChange}\n            color={this.state.color}\n            button={\n              <EuiColorPickerSwatch\n                color={this.state.color}\n                aria-label=\"Select a new color\"\n              />\n            }\n          />\n        </EuiFormRow>\n        <EuiColorPicker\n          onChange={this.handleChange}\n          color={this.state.color}\n          isInvalid={hasErrors}\n          button={\n            <EuiBadge\n              color={this.state.color ? this.state.color : 'hollow'}\n              onClickAriaLabel=\"Select a new color\">\n              Color this badge\n            </EuiBadge>\n          }\n        />\n      </Fragment>\n    );\n  }\n}\n"