import React, { cloneElement, Component } from 'react';
import PropTypes from "prop-types";
import classNames from 'classnames';
import { EuiFormControlLayoutIcons } from './form_control_layout_icons';
export { ICON_SIDES } from './form_control_layout_icons';

function isChildrenIsReactElement(append, prepend, children) {
  return (!!append || !!prepend) && children != null;
}

export class EuiFormControlLayout extends Component {
  render() {
    const {
      children,
      icon,
      clear,
      fullWidth,
      isLoading,
      isDisabled,
      compressed,
      className,
      prepend,
      append,
      readOnly,
      ...rest
    } = this.props;
    const classes = classNames('euiFormControlLayout', {
      'euiFormControlLayout--fullWidth': fullWidth,
      'euiFormControlLayout--compressed': compressed,
      'euiFormControlLayout--readOnly': readOnly,
      'euiFormControlLayout--group': prepend || append,
      'euiFormControlLayout-isDisabled': isDisabled
    }, className);
    const prependNodes = this.renderPrepends();
    const appendNodes = this.renderAppends();
    let clonedChildren;

    if (isChildrenIsReactElement(append, prepend, children)) {
      clonedChildren = cloneElement(children, {
        className: `${children.props.className} euiFormControlLayout__child--noStyle`
      });
    }

    return <div className={classes} {...rest}>
        {prependNodes}
        <div className="euiFormControlLayout__childrenWrapper">
          {clonedChildren || children}

          <EuiFormControlLayoutIcons icon={icon} clear={clear} isLoading={isLoading} />
        </div>
        {appendNodes}
      </div>;
  }

  renderPrepends() {
    const {
      prepend
    } = this.props;

    if (!prepend) {
      return;
    }

    const prependNodes = React.Children.map(prepend, (item, index) => this.createSideNode(item, 'prepend', index));
    return prependNodes;
  }

  renderAppends() {
    const {
      append
    } = this.props;

    if (!append) {
      return;
    }

    const appendNodes = React.Children.map(append, (item, index) => this.createSideNode(item, 'append', index));
    return appendNodes;
  }

  createSideNode(node, side, key) {
    return cloneElement(node, {
      className: `euiFormControlLayout__${side}`,
      key: key
    });
  }

}
EuiFormControlLayout.propTypes = {
  className: PropTypes.string,
  "aria-label": PropTypes.string,
  "data-test-subj": PropTypes.string,

  /**
       * Creates an input group with element(s) coming before children
       */
  prepend: PropTypes.oneOfType([PropTypes.element.isRequired, PropTypes.arrayOf(PropTypes.element.isRequired).isRequired]),

  /**
       * Creates an input group with element(s) coming after children
       */
  append: PropTypes.oneOfType([PropTypes.element.isRequired, PropTypes.arrayOf(PropTypes.element.isRequired).isRequired]),
  icon: PropTypes.any,
  clear: PropTypes.any,
  fullWidth: PropTypes.bool,
  isLoading: PropTypes.bool,
  isDisabled: PropTypes.bool,
  compressed: PropTypes.bool,
  readOnly: PropTypes.bool
};