module.exports = "import React, { Component, Fragment } from 'react';\nimport { times } from '../../../../src/services/utils';\nimport { Random } from '../../../../src/services/random';\nimport {\n  EuiHealth,\n  EuiCallOut,\n  EuiSpacer,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiCodeBlock,\n  EuiTitle,\n  EuiSwitch,\n  EuiBasicTable,\n  EuiSearchBar,\n} from '../../../../src/components';\n\nconst random = new Random();\n\nconst tags = [\n  { name: 'marketing', color: 'danger' },\n  { name: 'finance', color: 'success' },\n  { name: 'eng', color: 'success' },\n  { name: 'sales', color: 'warning' },\n  { name: 'ga', color: 'success' },\n];\n\nconst types = ['dashboard', 'visualization', 'watch'];\n\nconst users = ['dewey', 'wanda', 'carrie', 'jmack', 'gabic'];\n\nconst items = times(10, id => {\n  return {\n    id,\n    status: random.oneOf(['open', 'closed']),\n    type: random.oneOf(types),\n    tag: random.setOf(tags.map(tag => tag.name), { min: 0, max: 3 }),\n    active: random.boolean(),\n    owner: random.oneOf(users),\n    followers: random.integer({ min: 0, max: 20 }),\n    comments: random.integer({ min: 0, max: 10 }),\n    stars: random.integer({ min: 0, max: 5 }),\n  };\n});\n\nconst loadTags = () => {\n  return new Promise(resolve => {\n    setTimeout(() => {\n      resolve(\n        tags.map(tag => ({\n          value: tag.name,\n          view: <EuiHealth color={tag.color}>{tag.name}</EuiHealth>,\n        }))\n      );\n    }, 2000);\n  });\n};\n\nconst initialQuery = EuiSearchBar.Query.MATCH_ALL;\n\nexport class SearchBar extends Component {\n  constructor(props) {\n    super(props);\n    this.state = {\n      query: initialQuery,\n      result: items,\n      error: null,\n      incremental: false,\n    };\n  }\n\n  onChange = ({ query, error }) => {\n    if (error) {\n      this.setState({ error });\n    } else {\n      this.setState({\n        error: null,\n        result: EuiSearchBar.Query.execute(query, items, {\n          defaultFields: ['owner', 'tag', 'type'],\n        }),\n        query,\n      });\n    }\n  };\n\n  toggleIncremental = () => {\n    this.setState(prevState => ({ incremental: !prevState.incremental }));\n  };\n\n  renderSearch() {\n    const { incremental } = this.state;\n\n    const filters = [\n      {\n        type: 'field_value_toggle_group',\n        field: 'status',\n        items: [\n          {\n            value: 'open',\n            name: 'Open',\n          },\n          {\n            value: 'closed',\n            name: 'Closed',\n          },\n        ],\n      },\n      {\n        type: 'is',\n        field: 'active',\n        name: 'Active',\n        negatedName: 'Inactive',\n      },\n      {\n        type: 'field_value_toggle',\n        name: 'Mine',\n        field: 'owner',\n        value: 'dewey',\n      },\n      {\n        type: 'field_value_toggle',\n        name: 'Popular',\n        field: 'followers',\n        value: 5,\n        operator: 'gt',\n      },\n      {\n        type: 'field_value_selection',\n        field: 'tag',\n        name: 'Tag',\n        multiSelect: 'or',\n        cache: 10000, // will cache the loaded tags for 10 sec\n        options: () => loadTags(),\n      },\n    ];\n\n    const schema = {\n      strict: true,\n      fields: {\n        active: {\n          type: 'boolean',\n        },\n        status: {\n          type: 'string',\n        },\n        followers: {\n          type: 'number',\n        },\n        comments: {\n          type: 'number',\n        },\n        stars: {\n          type: 'number',\n        },\n        created: {\n          type: 'date',\n        },\n        owner: {\n          type: 'string',\n        },\n        tag: {\n          type: 'string',\n          validate: value => {\n            if (value !== '' && !tags.some(tag => tag.name === value)) {\n              throw new Error(\n                `unknown tag (possible values: ${tags\n                  .map(tag => tag.name)\n                  .join(',')})`\n              );\n            }\n          },\n        },\n      },\n    };\n\n    return (\n      <EuiSearchBar\n        defaultQuery={initialQuery}\n        box={{\n          placeholder: 'e.g. type:visualization -is:active joe',\n          incremental,\n          schema,\n        }}\n        filters={filters}\n        onChange={this.onChange}\n      />\n    );\n  }\n\n  renderError() {\n    const { error } = this.state;\n    if (!error) {\n      return;\n    }\n    return (\n      <Fragment>\n        <EuiCallOut\n          iconType=\"faceSad\"\n          color=\"danger\"\n          title={`Invalid search: ${error.message}`}\n        />\n        <EuiSpacer size=\"l\" />\n      </Fragment>\n    );\n  }\n\n  renderTable() {\n    const columns = [\n      {\n        name: 'Type',\n        field: 'type',\n      },\n      {\n        name: 'Open',\n        field: 'status',\n        render: status => (status === 'open' ? 'Yes' : 'No'),\n      },\n      {\n        name: 'Active',\n        field: 'active',\n        dataType: 'boolean',\n      },\n      {\n        name: 'Tags',\n        field: 'tag',\n      },\n      {\n        name: 'Owner',\n        field: 'owner',\n      },\n      {\n        name: 'Stats',\n        width: '150px',\n        render: item => {\n          return (\n            <div>\n              <div>{`${item.stars} Stars`}</div>\n              <div>{`${item.followers} Followers`}</div>\n              <div>{`${item.comments} Comments`}</div>\n            </div>\n          );\n        },\n      },\n    ];\n\n    const queriedItems = EuiSearchBar.Query.execute(this.state.query, items, {\n      defaultFields: ['owner', 'tag', 'type'],\n    });\n\n    return <EuiBasicTable items={queriedItems} columns={columns} />;\n  }\n\n  render() {\n    const { incremental, query } = this.state;\n\n    let esQueryDsl;\n    let esQueryString;\n\n    try {\n      esQueryDsl = EuiSearchBar.Query.toESQuery(query);\n    } catch (e) {\n      esQueryDsl = e.toString();\n    }\n    try {\n      esQueryString = EuiSearchBar.Query.toESQueryString(query);\n    } catch (e) {\n      esQueryString = e.toString();\n    }\n\n    const content = this.renderError() || (\n      <EuiFlexGroup>\n        <EuiFlexItem grow={4}>\n          <EuiTitle size=\"s\">\n            <h3>Elasticsearch Query String</h3>\n          </EuiTitle>\n          <EuiSpacer size=\"s\" />\n          <EuiCodeBlock language=\"js\">\n            {esQueryString ? esQueryString : ''}\n          </EuiCodeBlock>\n\n          <EuiSpacer size=\"l\" />\n\n          <EuiTitle size=\"s\">\n            <h3>Elasticsearch Query DSL</h3>\n          </EuiTitle>\n          <EuiSpacer size=\"s\" />\n          <EuiCodeBlock language=\"js\">\n            {esQueryDsl ? JSON.stringify(esQueryDsl, null, 2) : ''}\n          </EuiCodeBlock>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={6}>\n          <EuiTitle size=\"s\">\n            <h3>JS execution</h3>\n          </EuiTitle>\n\n          <EuiSpacer size=\"s\" />\n\n          {this.renderTable()}\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    );\n\n    return (\n      <Fragment>\n        <EuiFlexGroup alignItems=\"center\">\n          <EuiFlexItem>{this.renderSearch()}</EuiFlexItem>\n\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label=\"Incremental\"\n              checked={incremental}\n              onChange={this.toggleIncremental}\n            />\n          </EuiFlexItem>\n        </EuiFlexGroup>\n        <EuiSpacer size=\"l\" />\n        {content}\n      </Fragment>\n    );\n  }\n}\n"